use anyhow::Result;
use std::time::Instant;
use openxr as xr;
use glam::{Vec3,Quat};
use crate::{scene::{Scene,TABLE},log::Log,manipulation::{Grab,Table}};
pub struct Controls{trigger:xr::Action<bool>,grip:xr::Action<bool>,recenter:xr::Action<bool>,speed:xr::Action<bool>,stick:xr::Action<xr::Vector2f>,pose:xr::Action<xr::Posef>,haptic:xr::Action<xr::Haptic>,spaces:Option<[xr::Space;2]>,set:xr::ActionSet,hands:[xr::Path;2],previous:[[bool;3];2],last_down:[bool;2],last_input:Instant,grab:Grab}
fn axis(v:f32)->f32{if v.abs()<0.18{0.0}else{v.signum()*(v.abs()-0.18)/0.82}}
impl Controls{
 pub fn new(instance:&xr::Instance,log:&Log)->Result<Self>{let path=|s:&str|instance.string_to_path(s);let hands=[path("/user/hand/left")?,path("/user/hand/right")?];let set=instance.create_action_set("replay","리플레이 조작",0)?;let trigger=set.create_action::<bool>("table_grab","테이블 잡기와 재생",&hands)?;let grip=set.create_action::<bool>("seek","10초 탐색",&hands)?;let recenter=set.create_action::<bool>("recenter","처음 배치",&hands)?;let speed=set.create_action::<bool>("speed","배속",&hands)?;let stick=set.create_action::<xr::Vector2f>("table_adjust","높이 크기 거리 회전",&hands)?;let pose=set.create_action::<xr::Posef>("hand_pose","손 위치",&hands)?;let haptic=set.create_action::<xr::Haptic>("grab_feedback","잡기 진동",&hands)?;
  for profile in ["/interaction_profiles/oculus/touch_controller","/interaction_profiles/khr/simple_controller","/interaction_profiles/microsoft/motion_controller"]{let mut bindings=Vec::new();for hand in ["left","right"]{let p=|suffix:&str|path(&format!("/user/hand/{hand}/{suffix}"));bindings.push(xr::Binding::new(&pose,p("input/grip/pose")?));bindings.push(xr::Binding::new(&haptic,p("output/haptic")?));if profile.ends_with("simple_controller"){bindings.push(xr::Binding::new(&trigger,p("input/select/click")?));bindings.push(xr::Binding::new(&recenter,p("input/menu/click")?));}else{bindings.push(xr::Binding::new(&trigger,p("input/trigger/value")?));bindings.push(xr::Binding::new(&grip,p(if profile.contains("oculus"){"input/squeeze/value"}else{"input/squeeze/click"})?));bindings.push(xr::Binding::new(&stick,p("input/thumbstick")?));bindings.push(xr::Binding::new(&recenter,p(if profile.contains("oculus"){if hand=="left"{"input/x/click"}else{"input/a/click"}}else{"input/menu/click"})?));bindings.push(xr::Binding::new(&speed,p(if profile.contains("oculus"){if hand=="left"{"input/y/click"}else{"input/b/click"}}else{"input/thumbstick/click"})?));}}
   match instance.suggest_interaction_profile_bindings(path(profile)?,&bindings){Ok(())=>log.line(format!("컨트롤러 바인딩 제안 완료={profile}")),Err(e)=>log.line(format!("컨트롤러 프로필 제안 미지원={profile} 결과={e:?}"))}
  }Ok(Self{trigger,grip,recenter,speed,stick,pose,haptic,spaces:None,set,hands,previous:[[false;3];2],last_down:[false;2],last_input:Instant::now(),grab:Grab::default()})
 }
 pub fn attach(&mut self,session:&xr::Session<xr::D3D11>)->Result<()>{session.attach_action_sets(&[&self.set])?;self.spaces=Some([self.pose.create_space(session,self.hands[0],xr::Posef::IDENTITY)?,self.pose.create_space(session,self.hands[1],xr::Posef::IDENTITY)?]);Ok(())}
 pub fn cancel(&mut self,scene:&mut Scene){self.grab.cancel();self.last_input=Instant::now();self.previous=[[true;3];2];scene.hand_points=[None,None];scene.hand_grabbing=[false;2];}
 pub fn update(&mut self,session:&xr::Session<xr::D3D11>,space:&xr::Space,time:xr::Time,scene:&mut Scene,head:Vec3,q:Quat,dt:f32,floor:f32,log:&Log)->Result<()>{
  session.sync_actions(&[xr::ActiveActionSet::new(&self.set)])?;let mut down=[false;2];let mut positions=[None;2];let mut sticks=[xr::Vector2f{x:0.0,y:0.0};2];let mut recenter=false;
  for i in 0..2{let path=self.hands[i];let trigger=self.trigger.state(session,path)?;if trigger.is_active{self.last_down[i]=trigger.current_state;}down[i]=self.last_down[i];if self.pose.is_active(session,path)?{let location=self.spaces.as_ref().unwrap()[i].locate(space,time)?;if location.location_flags.contains(xr::SpaceLocationFlags::POSITION_VALID|xr::SpaceLocationFlags::POSITION_TRACKED){positions[i]=Some(Vec3::new(location.pose.position.x,location.pose.position.y,location.pose.position.z));}}
   let values=[self.grip.state(session,path)?,self.recenter.state(session,path)?,self.speed.state(session,path)?];for(j,state)in values.iter().enumerate(){let pressed=state.is_active&&state.current_state;if pressed&&!self.previous[i][j]{match j{0=>scene.seek(scene.time+if i==0{-600.0}else{600.0}),1=>recenter=true,2=>scene.cycle_speed(),_=>{}}}self.previous[i][j]=pressed;}let stick=self.stick.state(session,path)?;if stick.is_active{sticks[i]=stick.current_state;}
  }
  if recenter{self.cancel(scene);scene.table_height=floor+TABLE;scene.recenter(head,q);scene.notify_adjustment();return Ok(());}
  let mut table=Table{center:Vec3::new(scene.table_origin.x,scene.table_height,scene.table_origin.z),scale:scene.table_scale,yaw:scene.table_yaw};let input_dt=self.last_input.elapsed().as_secs_f32();self.last_input=Instant::now();let result=self.grab.step(down,positions,input_dt,&mut table,head,floor);if result.toggle{scene.toggle();}scene.hand_points=result.points;scene.hand_grabbing=result.grabbing;
  for i in 0..2{if result.haptic[i]{let vibration=xr::HapticVibration::new().amplitude(0.25).frequency(xr::FREQUENCY_UNSPECIFIED).duration(xr::Duration::from_nanos(30_000_000));if let Err(e)=self.haptic.apply_feedback(session,self.hands[i],&vibration){log.line(format!("잡기 진동 미지원={e:?}"));}}}
  if !self.grab.busy(){let(lx,ly,rx,ry)=(axis(sticks[0].x),axis(sticks[0].y),axis(sticks[1].x),axis(sticks[1].y));let mut forward=table.center-head;forward.y=0.0;if forward.length_squared()<0.0001{forward=q*Vec3::NEG_Z;forward.y=0.0;}forward=forward.normalize_or_zero();table.center+=forward*lx*dt*0.65;table.center.y+=ly*dt*0.45;table.yaw+=rx*dt*std::f32::consts::FRAC_PI_2;table.scale*= (ry*dt*0.6).exp();if lx.abs()+ly.abs()+rx.abs()+ry.abs()>0.001{table.constrain(head,floor);scene.notify_adjustment();}}
  if result.grabbing.iter().any(|&g|g){scene.notify_adjustment();}scene.table_origin.x=table.center.x;scene.table_origin.z=table.center.z;scene.table_height=table.center.y;scene.table_scale=table.scale;scene.table_yaw=table.yaw;Ok(())
 }
}
